const ERROR: f64 = f64::from_bits(0x3cf7_0000_0000_0006);

/// `round_grid`'s sign from its `f64` filter, or `None` when the filter's bound cannot certify it.
///
/// `Some(Sign::Zero)` only when the scale is zero, which makes the exact value zero; `None` also
/// for a rounded input outside its declared range.
#[inline]
#[must_use]
#[allow(
    clippy::many_single_char_names,
    clippy::similar_names,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn filter(z: P2, p: P2, cx: i128, cy: i128, w: i128) -> Option<Sign> {
    let ux = exact_f64(z.x) - exact_f64(p.x);
    let uy = exact_f64(z.y) - exact_f64(p.y);
    let w = rounded_f64(w, 83)?;
    let z_x = exact_f64(z.x);
    let tx_1 = w * z_x;
    let p_x = exact_f64(p.x);
    let tx_2 = w * p_x;
    let tx_3 = tx_1 + tx_2;
    let cx = rounded_f64(cx, 124)?;
    let tx_4 = tx_3 - cx;
    let tx = tx_4 - cx;
    let z_y = exact_f64(z.y);
    let ty_1 = w * z_y;
    let p_y = exact_f64(p.y);
    let ty_2 = w * p_y;
    let ty_3 = ty_1 + ty_2;
    let cy = rounded_f64(cy, 124)?;
    let ty_4 = ty_3 - cy;
    let ty = ty_4 - cy;
    let s_1 = ux * tx;
    let s_2 = uy * ty;
    let s = s_1 + s_2;
    let m_x = largest_magnitude([ux, z_x, p_x]);
    let m_y = largest_magnitude([uy, z_y, p_y]);
    let m_c = largest_magnitude([cx, cy]);
    let m_w = largest_magnitude([w]);
    let scale = larger(m_y * m_c, m_y * m_y * m_w);
    let scale = larger(scale, m_x * m_c);
    let scale = larger(scale, m_x * m_x * m_w);
    decide(s, ERROR, scale)
}

/// `round_grid`'s exact value: each step in the type its certificate gives it, with checked
/// arithmetic; `None` only if a step overflowed, which the certificate rules out; `None` also for a
/// rounded input outside its declared range.
#[inline]
#[must_use]
#[allow(
    clippy::many_single_char_names,
    clippy::similar_names,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn value(z: P2, p: P2, cx: i128, cy: i128, w: i128) -> Option<I256> {
    let ux = z.x.get().checked_sub(p.x.get())?;
    let uy = z.y.get().checked_sub(p.y.get())?;
    let w = within(w, 83)?;
    let z_x = z.x.get();
    let tx_1 = w.checked_mul(i128::from(z_x))?;
    let p_x = p.x.get();
    let tx_2 = w.checked_mul(i128::from(p_x))?;
    let tx_3 = tx_1.checked_add(tx_2)?;
    let cx = within(cx, 124)?;
    let tx_4 = tx_3.checked_sub(cx)?;
    let tx = tx_4.checked_sub(cx)?;
    let z_y = z.y.get();
    let ty_1 = w.checked_mul(i128::from(z_y))?;
    let p_y = p.y.get();
    let ty_2 = w.checked_mul(i128::from(p_y))?;
    let ty_3 = ty_1.checked_add(ty_2)?;
    let cy = within(cy, 124)?;
    let ty_4 = ty_3.checked_sub(cy)?;
    let ty = ty_4.checked_sub(cy)?;
    let s_1 = I256::product_i128(i128::from(ux), tx)?;
    let s_2 = I256::product_i128(i128::from(uy), ty)?;
    let s = s_1.checked_add(&s_2)?;
    Some(s)
}

/// `round_grid`'s exact sign: the sign of [`value`], or `None` as for [`value`].
#[inline]
#[must_use]
